// Des: Commands export, report, backup, retry, undo: owner data out, support bundle, safety copy, second chance, take back
// Flo: read store > write atomic files under the data root > print where > retry resets an item > undo recalls the last own message
// I/O: Ctx (caller) > files in stat/export, stat/report, stat/backup; stdout text; exit 0, 3 when nothing to do
// ===================================================================
const std = @import("std"); const ctxz = @import("ct-ctrl-ctxz.zig"); const file = @import("st-stor-file.zig"); const flo = @import("st-flow-data.zig"); const sess = @import("ru-sess-ctxz.zig"); const acts = @import("ru-chat-acts.zig"); const data = @import("st-stat-data.zig");
const CF = .{ .vers = "0.2.0", .logs = 50 };
const Row = struct { t: []const u8, chat: []const u8 = "", who: []const u8 = "", body: []const u8 = "", ts: i64 = 0, lvl: []const u8 = "", job: []const u8 = "" };
pub fn rowsOf(aren: std.mem.Allocator, sto: *data.Stor) ![]u8 { var out: std.ArrayList(u8) = .empty; var stm = try sto.dbzz.prep("SELECT chat,who,body,ts FROM msgs ORDER BY id;"); defer stm.fini(); while (try stm.step()) { try out.appendSlice(aren, try std.json.Stringify.valueAlloc(aren, Row{ .t = "msg", .chat = stm.colText(0), .who = stm.colText(1), .body = stm.colText(2), .ts = stm.colInt(3) }, .{})); try out.append(aren, '\n'); } const logs = try sto.logTail(aren, 100000); for (logs) |lg| { try out.appendSlice(aren, try std.json.Stringify.valueAlloc(aren, Row{ .t = "log", .lvl = lg.lvl, .job = lg.job, .body = lg.msg, .ts = lg.ts }, .{})); try out.append(aren, '\n'); } return out.items; }
pub fn exportRun(ctx: *ctxz.Ctx) !u8 { var sto = try ctxz.openStor(ctx); defer sto.close(); const body = try rowsOf(ctx.allo, &sto); const path = try std.fmt.allocPrint(ctx.allo, "{s}{c}export{c}za-export-{d}.jsonl", .{ ctx.stat, std.fs.path.sep, std.fs.path.sep, ctxz.nowMs(ctx) }); try file.fileAtom(ctx.allo, ctx.iozz, path, body); try ctxz.emitf(ctx, "exported to {s}\n", .{path}); return 0; }
pub fn reportText(aren: std.mem.Allocator, sto: *data.Stor, cfgjson: []const u8, probes: []const []const u8) ![]u8 { var out: std.ArrayList(u8) = .empty; try out.appendSlice(aren, try std.fmt.allocPrint(aren, "za {s} report\n", .{CF.vers})); try out.appendSlice(aren, "config (paths removed):\n"); try out.appendSlice(aren, cfgjson); try out.appendSlice(aren, "\nlast log lines (message text is hashed unless logz_body_enab):\n"); const logs = try sto.logTail(aren, CF.logs); for (logs) |lg| try out.appendSlice(aren, try std.fmt.allocPrint(aren, "{d} {s} {s}: {s}\n", .{ lg.ts, lg.lvl, lg.job, lg.msg })); try out.appendSlice(aren, "probes:\n"); for (probes) |nam| try out.appendSlice(aren, try std.fmt.allocPrint(aren, "{s}\n", .{nam})); return out.items; }
pub fn reportRun(ctx: *ctxz.Ctx) !u8 { var sto = try ctxz.openStor(ctx); defer sto.close(); var safe = ctx.cfg; safe.data_loca_wind = ""; safe.data_loca_unix = ""; safe.outb_dirz_path = ""; safe.brow_exec_path = ""; safe.labl_file_path = ""; const cfgjson = try std.json.Stringify.valueAlloc(ctx.allo, safe, .{}); var probes: std.ArrayList([]const u8) = .empty; const pdir = try std.fs.path.join(ctx.allo, &.{ ctx.stat, "probe" }); if (std.Io.Dir.cwd().openDir(ctx.iozz, pdir, .{ .iterate = true })) |dh| { var dirh = dh; defer dirh.close(ctx.iozz); var itr = dirh.iterate(); while (try itr.next(ctx.iozz)) |ent| { if (ent.kind == .file) try probes.append(ctx.allo, try ctx.allo.dupe(u8, ent.name)); } } else |_| {} const txt = try reportText(ctx.allo, &sto, cfgjson, probes.items); const path = try std.fs.path.join(ctx.allo, &.{ ctx.stat, "report", "report.txt" }); try file.fileAtom(ctx.allo, ctx.iozz, path, txt); try ctxz.emitf(ctx, "report saved: {s} (no chat text, no paths)\n", .{path}); return 0; }
pub fn backupRun(ctx: *ctxz.Ctx) !u8 { var sto = try ctxz.openStor(ctx); defer sto.close(); const dir = try std.fs.path.join(ctx.allo, &.{ ctx.stat, "backup" }); try std.Io.Dir.cwd().createDirPath(ctx.iozz, dir); const path = try std.fmt.allocPrint(ctx.allo, "{s}{c}za-stat-{d}.db", .{ dir, std.fs.path.sep, ctxz.nowMs(ctx) }); try sto.backup(path); try ctxz.emitf(ctx, "backup saved: {s}\n", .{path}); return 0; }
pub fn retryRun(ctx: *ctxz.Ctx) !u8 { if (ctx.args.rest.len != 1) return error.BadJob; const idz = std.fmt.parseInt(i64, ctx.args.rest[0], 10) catch return error.BadJob; var sto = try ctxz.openStor(ctx); defer sto.close(); const lat = (try flo.flowLatest(&sto, ctx.allo)) orelse return error.BadJob; const its = try flo.itemsOf(&sto, ctx.allo, lat.id); for (its) |itm| { if (itm.id != idz) continue; if (std.mem.eql(u8, itm.state, "done")) { try ctxz.emit(ctx, "that item is already done\n"); return 3; } try flo.itemSet(&sto, idz, "todo", ""); try flo.flowSet(&sto, lat.id, "partial"); try ctxz.emitf(ctx, "item {d} will run again: za go --live\n", .{idz}); return 0; } return error.BadJob; }
pub fn undoRun(ctx: *ctxz.Ctx) !u8 { if (ctx.args.rest.len != 1 or !std.mem.eql(u8, ctx.args.rest[0], "last")) return error.BadJob; var sto = try ctxz.openStor(ctx); defer sto.close(); const chat = (try sto.lastSend(ctx.allo)) orelse { try ctxz.emit(ctx, "nothing to undo\n"); return 3; }; var live = try ctxz.openLive(ctx, false); defer live.close(); var ses = sess.Sess.init(ctx.init.gpa, ctx.iozz, ctx.allo, ctx.cfg, &sto, live.conn, ctx.args.mode); ses.job = "undo"; const done = try acts.recallLast(&ses, chat); try ctxz.emitf(ctx, "{s} the last message in {s}\n", .{ if (done) "recalled" else "would recall", chat }); if (!done) try ctxz.emit(ctx, "nothing was changed (recall needs --live --force)\n"); return 0; }
